def _make_decorator_fab(deco):
    """Creates a decorator factory from the given deco function."""
    def decorator_fab(*dargs, **dkwargs):
        return make_decorator(deco, dargs, dkwargs)
    return decorator_fab


def decorator(deco):
    """
    Transforms a flat wrapper into decorator::

        @decorator
        def func(call, methods, content_type=DEFAULT):  # These are decorator params
            # Access call arg by name
            if call.request.method not in methods:
                # ...
            # Decorated functions and all the arguments are accesible as:
            print(call._func, call_args, call._kwargs)
            # Finally make a call:
            return call()
    """
    if has_single_arg(deco):
        return make_decorator(deco)
    elif has_1pos_and_kwonly(deco):
        # Function has 1 positional arg + optional keyword-only args
        # Return a decorator factory that can be called with or without args
        decorator_fab = _make_decorator_fab(deco)
        # Make it callable directly on a function too
        def direct_decorator(func):
            return make_decorator(deco, (), {})(func)
        # Use wraps to copy metadata
        wrapped = wraps(deco)(direct_decorator)
        # Also expose the factory
        wrapped.decorator_fab = decorator_fab
        return wrapped
    else:
        # Any arguments after first become decorator arguments
        # And a decorator with arguments is essentialy a decorator fab
        decorator_fab = _make_decorator_fab(deco)
        return wraps(deco)(decorator_fab)


# Expose decorator_fab at module level for import
decorator_fab = _make_decorator_fab

